CREATE TABLE IF NOT EXISTS game_catalog (
  code VARCHAR(32) PRIMARY KEY, name VARCHAR(80) NOT NULL, is_active BOOLEAN NOT NULL DEFAULT TRUE, sort_order INT NOT NULL DEFAULT 0, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS service_categories (
  id BIGINT AUTO_INCREMENT PRIMARY KEY, game_code VARCHAR(32) NOT NULL, code VARCHAR(32) NOT NULL, name VARCHAR(80) NOT NULL, is_active BOOLEAN NOT NULL DEFAULT TRUE, sort_order INT NOT NULL DEFAULT 0, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT uk_service_category_game_code UNIQUE (game_code, code)
);
